#!/bin/bash
set -euo pipefail
test "$(id -un)" = pwa209
case "$(hostname -f)" in *.narval.calcul.quebec) ;; *) exit 2 ;; esac
python3 -B -u - <<'PY'
from pathlib import Path
import base64,json,subprocess,shlex,os,hashlib
assert os.geteuid()==3164768
s=Path('/scratch/pwa209/horsehair-worm/maintenance/storage-recovery-handoff-v3-20261103');s.mkdir()
code=base64.b64decode('');text=base64.b64decode('')
(s/'release-census.py').write_bytes(code);p=s/'handoff.sbatch';p.write_bytes(text)
(s/'source-manifest.json').write_text(json.dumps({'release-census.py':hashlib.sha256(code).hexdigest(),'handoff.sbatch':hashlib.sha256(text).hexdigest()}))
cmd=['sbatch','--parsable','--dependency=afterok:8420757',str(p)];(s/'submit-intent.json').write_text(json.dumps(cmd))
q=subprocess.run(cmd,text=True,capture_output=True,timeout=90);(s/'submit-response.json').write_text(json.dumps({'code':q.returncode,'stdout':q.stdout,'stderr':q.stderr}));q.check_returncode();job=q.stdout.strip().split(';')[0];assert job.isdigit()
def observe():
 q=subprocess.run(['scontrol','show','job',job,'-o'],text=True,capture_output=True,timeout=90);q.check_returncode();f=dict(x.split('=',1) for x in shlex.split(q.stdout) if '=' in x)
 assert f['JobId']==job and f['UserId']=='pwa209(3164768)' and f['Command']==str(p) and f['JobName']=='hhw-storage-recovery-handoff-v3-20261103'
 return f
f=observe();assert f['JobState']=='PENDING' and f['Reason']=='JobHeldUser';(s/'held.json').write_text(json.dumps(f))
(s/'release-intent.json').write_text(json.dumps(['scontrol','release',job]));q=subprocess.run(['scontrol','release',job],text=True,capture_output=True,timeout=90);(s/'release-response.json').write_text(json.dumps({'code':q.returncode,'stdout':q.stdout,'stderr':q.stderr}))
f=observe();assert f['JobState']=='PENDING' and f['Reason'] not in ['JobHeldUser','JobHeldAdmin'] and int(f['Priority'])>0 or f['JobState']=='RUNNING'
(s/'registration.json').write_text(json.dumps({'job_id':job,'actual_unheld':f},indent=2));print('STORAGE_HANDOFF '+job,flush=True)
PY
